python3 -B -c import subprocess,json,collections; from pathlib import Path; w=Path(".runs/mixed-01-treatment").resolve(); data=subprocess.check_output(["entire","checkpoint","explain","--commit","HEAD","--transcript","--session-index","0"],cwd=w,timeout=30); events=[json.loads(x) for x in data.splitlines()]; types=collections.Counter(); samples={}; meta=[]; times=[]; malformed=0
for event in events:
 p=event.get("payload",{}); i=p.get("item",{}); kind=str(i.get("type")) if isinstance(i,dict) else "non-dict"; types[(str(event.get("type")),str(p.get("type")),kind)]+=1
 if event.get("type")=="session_meta": meta.append({"event_keys":list(event),"payload_keys":list(p),"id":p.get("id"),"cwd":p.get("cwd"),"timestamp":event.get("timestamp")})
 if p.get("type")=="item_completed" and kind not in samples: samples[kind]={"event_keys":list(event),"payload_keys":list(p),"item_keys":list(i),"timestamp":event.get("timestamp"),"item_status":i.get("status")}
 if event.get("timestamp"): times.append(event["timestamp"])
print(json.dumps({"line_count":len(events),"type_counts":[{"kind":k,"count":v} for k,v in types.items()],"identity_schema":meta,"completed_item_schemas":samples,"first_timestamp":times[0] if times else None,"last_timestamp":times[-1] if times else None},indent=2))

